use serde_json::{Value, Error};

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        let mut result = String::new();
        for byte in arr {
            if let Value::Number(num) = byte {
                if let Some(num) = num.as_i64() {
                    if num >= 0 && num <= 255 {
                        result.push_str(&format!("{:02x}", num));
                    }
                }
            }
        }
        Value::String(result)
    } else {
        Value::Null
    }
}
